def max_sum(arr,n):
  increasing = [1]*n
  decreasing = [1]*n

  for i in range(1,n):
      if arr[i]>arr[i-1]:
          increasing[i]=increasing[i-1]+1

  for i in range(n-2,-1,-1):
      if arr[i]>arr[i+1]:
          decreasing[i]=decreasing[i+1]+1

  max_sum = 0
  for i in range(n):
      max_sum = max(max_sum,increasing[i]+decreasing[i]-1)

  return max_sum

def babylonian_squareroot(num):
  guess = num / 2.0
  while abs(guess * guess - num) > 0.0001:
    guess = (guess + num / guess) / 2.0
  return guess

